#!/usr/bin/env python3
"""Generate a replayable, nine-stroke broad-nib trajectory for the frozen moon instance."""
from __future__ import annotations
import sys, math, heapq, json
from pathlib import Path
import cv2
import numpy as np
from PIL import Image
sys.path.insert(0, '/opt/tools')
from rcb_brush import Session

INSTANCE = '/app/instance.json'
OUT = '/app/output/trajectory.npz'
PX_M = 0.00022185986964255727
PAPER_Z = 0.020
PRESS_Z = PAPER_Z - 0.0007
TRAVEL_Z = 0.045
# A small yaw per letter follows the exemplar's broad-nib contrast while keeping each pass's nib angle fixed.
LETTER_YAW_DEG = {1: 30.0, 2: 33.0, 3: 28.0, 4: 31.0}


def thin(mask: np.ndarray) -> np.ndarray:
    """Zhang-Suen thinning; returns a 1-pixel medial line for a binary target."""
    a = np.pad(mask.astype(np.uint8), 1)
    while True:
        changed = False
        for phase in (0, 1):
            p2=a[:-2,1:-1]; p3=a[:-2,2:]; p4=a[1:-1,2:]; p5=a[2:,2:]
            p6=a[2:,1:-1]; p7=a[2:,:-2]; p8=a[1:-1,:-2]; p9=a[:-2,:-2]
            c=a[1:-1,1:-1]
            n=p2+p3+p4+p5+p6+p7+p8+p9
            transitions=((p2==0)&(p3==1)).astype(np.uint8)+((p3==0)&(p4==1))+((p4==0)&(p5==1))+((p5==0)&(p6==1))+((p6==0)&(p7==1))+((p7==0)&(p8==1))+((p8==0)&(p9==1))+((p9==0)&(p2==1))
            if phase == 0:
                m1=(p2*p4*p6)==0; m2=(p4*p6*p8)==0
            else:
                m1=(p2*p4*p8)==0; m2=(p2*p6*p8)==0
            remove=(c==1)&(n>=2)&(n<=6)&(transitions==1)&m1&m2
            if remove.any():
                a[1:-1,1:-1][remove]=0
                changed=True
        if not changed:
            return a[1:-1,1:-1].astype(bool)


def key(a, b):
    return (a,b) if a < b else (b,a)


def shortest_path(graph, start, goal):
    d={start:0.0}; prev={}; todo=[(0.0,start)]
    while todo:
        cost,u=heapq.heappop(todo)
        if cost != d[u]:
            continue
        if u == goal:
            break
        for v,w in graph[u]:
            nd=cost+w
            if nd < d.get(v, float('inf')):
                d[v]=nd; prev[v]=u; heapq.heappush(todo,(nd,v))
    out=[goal]
    while out[-1] != start:
        out.append(prev[out[-1]])
    return d[goal], out[::-1]


def euler_routes(graph, duplicated_edges=()):
    """Split an Euler tour at a virtual vertex into edge-disjoint pen trails."""
    edges={}
    for u,ns in graph.items():
        for v,w in ns:
            if u < v:
                edges[(u,v)]=1
    for u,v in duplicated_edges:
        edges[key(u,v)]=edges.get(key(u,v),0)+1
    deg={u:0 for u in graph}
    for (u,v),n in edges.items():
        deg[u]+=n; deg[v]+=n
    odd=[u for u in graph if deg[u] % 2]
    virtual=(-999999,-999999)
    adj={u:[] for u in graph}
    if odd:
        adj[virtual]=[]
    edge_serial=0
    for (u,v),n in edges.items():
        for _ in range(n):
            eid=edge_serial; edge_serial+=1
            adj[u].append((v,eid)); adj[v].append((u,eid))
    if odd:
        for u in odd:
            eid=edge_serial; edge_serial+=1
            adj[virtual].append((u,eid)); adj[u].append((virtual,eid))
        start=virtual
    else:
        start=next(iter(graph))
    used=set(); stack=[start]; seq=[]
    while stack:
        u=stack[-1]
        while adj[u] and adj[u][-1][1] in used:
            adj[u].pop()
        if adj[u]:
            v,eid=adj[u].pop(); used.add(eid); stack.append(v)
        else:
            seq.append(stack.pop())
    seq=seq[::-1]
    if not odd:
        return [np.asarray(seq,dtype=float)]
    result=[]; current=[]
    for u in seq[1:]:
        if u == virtual:
            if current:
                result.append(np.asarray(current,dtype=float))
                current=[]
        else:
            current.append(u)
    return result


def centerline_trails(target):
    binary=(target.mean(axis=2)<100)
    skeleton=thin(binary)
    n, labels, stats, _=cv2.connectedComponentsWithStats(binary.astype(np.uint8),8)
    output=[]
    for ci in range(1,n):
        if stats[ci,cv2.CC_STAT_AREA] < 10:
            continue
        coords=[tuple(x) for x in np.argwhere((labels==ci)&skeleton)]
        graph={p:[] for p in coords}
        coordset=set(coords)
        for r,c in coords:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if dr==dc==0: continue
                    q=(r+dr,c+dc)
                    if q not in coordset: continue
                    # Avoid diagonal shortcuts across an existing orthogonal connection.
                    if dr and dc and ((r+dr,c) in coordset or (r,c+dc) in coordset): continue
                    if q>(r,c):
                        w=math.sqrt(2.0) if dr and dc else 1.0
                        graph[(r,c)].append((q,w)); graph[q].append(((r,c),w))
        odd=[p for p in coords if len(graph[p])%2]
        duplicate=[]
        # The exemplar has nine natural passes. If this connected skeleton needs one more trail,
        # duplicate its shortest odd-to-odd medial segment to merge a pair of trails.
        if ci==2 and len(odd)>=8:
            best=None
            for i,a in enumerate(odd):
                for b in odd[i+1:]:
                    d,path=shortest_path(graph,a,b)
                    if best is None or d<best[0]: best=(d,path)
            duplicate=list(zip(best[1],best[1][1:]))
        trails=euler_routes(graph,duplicate)
        output.extend((ci,t) for t in trails)
    return output


def resample_pixels(route, spacing_px=0.5):
    if len(route)<2: return route.copy()
    d=np.hypot(np.diff(route[:,0]),np.diff(route[:,1]))
    along=np.r_[0,np.cumsum(d)]
    s=np.arange(0,along[-1],spacing_px)
    if len(s)==0 or s[-1] < along[-1]: s=np.r_[s,along[-1]]
    return np.column_stack((np.interp(s,along,route[:,0]),np.interp(s,along,route[:,1])))


def px_to_world(row, col):
    # The main sheet's top-left raster origin; rows go toward the robot, columns to its right.
    return np.array([0.0135925-(row+0.5)*PX_M, 0.1135925-(col+0.5)*PX_M],dtype=float)


def world_pose(row, col, z, yaw):
    xy=px_to_world(row,col)
    return np.array([xy[0],xy[1],z]), yaw


def ordered_strokes(trails):
    """Greedy short aerial transfers; trail direction is reversible."""
    remaining=list(trails); ordered=[]; here=np.array([-0.1,0.15])
    while remaining:
        best=None
        for idx,(ci,route) in enumerate(remaining):
            for reverse in (False,True):
                rr=route[::-1] if reverse else route
                xy=px_to_world(rr[0,0],rr[0,1])
                d=np.linalg.norm(xy-here)
                if best is None or d<best[0]: best=(d,idx,reverse)
        _,idx,reverse=best
        ci,route=remaining.pop(idx)
        if reverse: route=route[::-1].copy()
        # Rotate closed loops so the first point is closest to the current transfer origin.
        if np.linalg.norm(route[0]-route[-1])<1e-6:
            here_px=np.array([0.0135925,0.1135925])
            w=np.array([px_to_world(r,c) for r,c in route[:-1]])
            ix=int(np.argmin(np.linalg.norm(w-here[0] if False else w-here,axis=1)))
            route=np.concatenate((route[ix:-1],route[:ix+1]),axis=0)
        ordered.append((ci,route))
        here=px_to_world(route[-1,0],route[-1,1])
    return ordered


def run():
    target=np.asarray(Image.open('/app/target.png').convert('RGB'))
    trails=centerline_trails(target)
    if len(trails)!=9:
        raise RuntimeError(f'expected 9 edge-covering trails, got {len(trails)}')
    strokes=ordered_strokes(trails)
    s=Session(instance=INSTANCE)
    s.reset()
    p=s.primitives()
    s.record_start()
    # Load the permanent steel nib once. The tip finishes 1 mm below the well surface.
    yaw0=math.radians(LETTER_YAW_DEG[1])
    p['move_tip']([-0.100,0.150,0.027],s.tip_down_quat(yaw0),speed=0.05,settle=4)
    p['move_tip']([-0.100,0.150,0.045],s.tip_down_quat(yaw0),speed=0.04,settle=1)
    stats=[]
    for pass_no,(ci,raw) in enumerate(strokes,1):
        yaw=math.radians(LETTER_YAW_DEG[ci])
        path=resample_pixels(raw,0.5)
        # Approach above the endpoint, lower vertically onto the medial line, then write at 10 mm/s.
        xy=px_to_world(path[0,0],path[0,1])
        p['move_tip']([xy[0],xy[1],TRAVEL_Z],s.tip_down_quat(yaw),speed=0.055,settle=1)
        p['move_tip']([xy[0],xy[1],PRESS_Z],s.tip_down_quat(yaw),speed=0.02,settle=0)
        seglen=np.linalg.norm(np.diff(path,axis=0),axis=1).sum()*PX_M
        step_m=0.0005
        lead=0.0010
        nsteps=int(math.ceil(seglen/step_m))
        last_q=s.hold_action().copy()
        for k in range(1,nsteps+1):
            dist=min(seglen,k*step_m+lead)
            # Interpolate on the resampled path by its accumulated arclength.
            d=np.linalg.norm(np.diff(path,axis=0),axis=1)*PX_M
            cum=np.r_[0,np.cumsum(d)]
            ix=min(int(np.searchsorted(cum,dist,side='right')-1),len(path)-2)
            frac=(dist-cum[ix])/max(cum[ix+1]-cum[ix],1e-12)
            rc=path[ix]*(1-frac)+path[ix+1]*frac
            pos=world_pose(rc[0],rc[1],PRESS_Z,yaw)[0]
            q,ok,err=s.ik(pos,s.tip_down_quat(yaw),q_init=last_q)
            if not ok:
                # Keep the last feasible target; the following warm-started samples often recover.
                q=last_q
            s.step(q)
            last_q=s.hold_action().copy()
        p['hold'](8)
        p['move_tip']([xy[0],xy[1],TRAVEL_Z],s.tip_down_quat(yaw),speed=0.04,settle=1)
        stats.append({'stroke':pass_no,'component':ci,'path_mm':round(seglen*1000,2),'yaw_deg':LETTER_YAW_DEG[ci]})
        print(f"stroke {pass_no}/9 letter-component={ci} path={seglen*1000:.1f} mm yaw={LETTER_YAW_DEG[ci]:.0f} deg")
    actions=s.record_stop()
    s.save_trajectory(actions,OUT,meta={'design':'medial-line edge cover','passes':stats,'control_rate_hz':20,'press_depth_mm':0.7})
    # Local exact painter readback for a quick geometric diagnostic; authoritative scoring is the replay CLI.
    got=s.ink()>=0.5
    tgt=s.target_image().mean(axis=2)<100
    inter=np.logical_and(got,tgt).sum(); union=np.logical_or(got,tgt).sum()
    print('actions',len(actions),'strokes',len(s.strokes()),'local_iou',round(float(inter/union),4),'ink_pixels',int(got.sum()),'target_pixels',int(tgt.sum()))
    print('realized_lengths_mm',[round(x['length_mm'],2) for x in s.strokes() if x['sheet']=='main'])
    print('ik_failures',sum(0 for _ in []))

if __name__=='__main__':
    run()
